// Hilt, generated by KSP: for the app, which owns the graph, and for the
// features, whose view models it constructs. Only the app needs Hilt's Gradle
// plugin — it rewrites the entry points and gathers every module's bindings —
// a feature's @HiltViewModel classes need just the annotation processor.
plugins {
    id("com.google.devtools.ksp")
}

pluginManager.withPlugin("com.android.application") {
    pluginManager.apply("com.google.dagger.hilt.android")
}

val libs = the<VersionCatalogsExtension>().named("libs")
fun lib(alias: String) = libs.findLibrary(alias).get()

dependencies {
    "implementation"(lib("hilt-android"))
    "ksp"(lib("hilt-compiler"))
}
